const uint8_t *smc_system_icon(const char *sys, size_t *len) {
    for (size_t i = 0; i < sizeof(icons) / sizeof(icons[0]); i++)
        if (!strcmp(icons[i].sys, sys)) {
            *len = icons[i].len;
            return icons[i].data;
        }
    return NULL;
}
